const url=id=>"#/artikel/"+encodeURIComponent(id), al=(id,text)=>'<a href="'+url(id)+'">'+E(text||A(id)?.title||id)+'</a>';
let favorites=[];try{favorites=JSON.parse(localStorage.getItem("atlas-favorites-v4")||"[]");if(!Array.isArray(favorites))favorites=[]}catch{favorites=[]}
let graphFocus="sozialhilfe",graphFilter="Sozialhilfe",graphZoom=1,graphTx=0,graphTy=0,caseNum=0,quizPos=0,quizPoints=0,quizDone=false;
const navItems=[["start","⌂","Startseite"],["wissen","▦","Wissensgebiete"],["sozialwissenschaften","◉","Sozialwissenschaften"],["forschungsdossiers","◈","Forschungsdossiers"],["studienatlas","⌕","Studienatlas"],["migration","◎","Migration & Asyl"],["kantone","◈","26 Kantone"],["laender","◈","Europa"],["recht","§","Rechtsbibliothek"],["fachlexikon","Aa","Fachlexikon"],["infografiken","▧","Infografiken"],["falllabor","◇","Falllabor"],["werkzeuge","✧","Werkzeuge"],["hilfe","?","Anleitung"]];
const sections=[...new Set(D.topics.map(t=>t.category))];
const detailCount=D.topics.length;
const bubble=(s,gray=false)=>'<span class="pill'+(gray?" badge-gray":"")+'">'+E(s)+'</span>';
function card(href,symbol,title,desc){return '<a class="card" href="'+href+'"><span class="symbol">'+E(symbol)+'</span><strong>'+E(title)+'</strong><p>'+E(desc)+'</p></a>'}
function crumb(items){return '<div class="crumb">'+items.map((it,i)=>i===items.length-1?E(it[1]):'<a href="'+it[0]+'">'+E(it[1])+'</a>').join(" / ")+'</div>'}
function sourceList(sources){return sources.map(s=>'<a class="listline" href="'+E(s.url)+'" target="_blank" rel="noopener noreferrer"><strong>'+E(s.label)+' ↗</strong><small>Amtliche bzw. fachliche Primärquelle öffnen</small></a>').join("")}
function lawLink(l){return '<a href="'+E(l.url)+'" target="_blank" rel="noopener noreferrer">'+E(l.code)+' · '+E(l.title)+' ↗</a>'}
function home(){if(window.ATLAS_STRUCTURE_V13)return window.ATLAS_STRUCTURE_V13.home();
const recommended=["sozialhilfe","ahv","iv","el","alv","graubuenden"];
return '<div class="hero"><span class="eyebrow">SOCIAL ATLAS · WISSENSCHAFTLICHE FACHENZYKLOPÄDIE</span><h1>Die soziale Sicherheit.<br>Als vernetztes Universum.</h1><p>Entdecke die Schweizer Sozialversicherungen, kantonale Sozialhilfe und europäische Systeme – mit Fachartikeln, Gesetzesquellen, interaktiven Verbindungen und einem praxisnahen Falllabor.</p><div class="heroActions"><a class="btn" href="#/netzwerk">Netzwerk entdecken ↗</a><a class="btn outline" href="#/wissen">Enzyklopädie öffnen</a><a class="btn outline" href="#/hilfe">Anleitung</a></div></div>'+
'<div class="statrow"><div class="stat"><b>'+D.topics.length+'</b><span>Vertiefte Wissensthemen</span></div><div class="stat"><b>'+D.laws.length+'</b><span>Ausgewählte Rechtsreferenzen</span></div><div class="stat"><b>26</b><span>Kantonsprofile</span></div><div class="stat"><b>6</b><span>Ländersysteme</span></div></div>'+
(window.ATLAS_V5?.home()||"")+(window.ATLAS_V7?.overview()||"")+(window.ATLAS_MIGRATION?.home()||"")+(window.ATLAS_HUMANITIES?.home()||"")+(window.ATLAS_V6?.miniHome()||"")+'<div class="sectionbar"><h2>Das Wissen vernetzt erkunden</h2><small>Interaktiv statt nur lesen</small></div><div class="cards">'+card("#/netzwerk","✳","Lebendiges Systemnetz","Versicherungen anklicken, Beziehungen verfolgen und in den Artikel springen.")+card("#/assistent","⌕","Fragen stellen","Wissensbasierte Antworten mit Quellen direkt in der App.")+card("#/falllabor","◇","Fallbearbeitung","Schrittweise Fallprüfung mit Gesetzesartikeln und Verbindungen.")+card("#/generator","✎","Eigene Fälle erzeugen","Lernfälle variieren, Checklisten erstellen und ausdrucken.")+'</div>'+
'<div class="sectionbar"><h2>Wichtige Einstiegsthemen</h2><small>Mehr erfahren →</small></div><div class="cards">'+recommended.map(id=>{const t=A(id);return card(url(id),t.short,t.title,t.summary)}).join("")+'</div>'+
(favorites.length?'<h2>Deine gemerkten Artikel</h2><div class="bookmarks">'+favorites.filter(id=>A(id)).map(id=>'<a class="btn small" href="'+url(id)+'">★ '+E(A(id).short)+'</a>').join("")+'</div>':'')+
'<div class="note"><b>Wissensstand und Grenzen</b><p>Enthalten sind strukturierte Grundlagen, ausgewählte Rechtsverweise sowie alle Kantone als Navigation. Nur Graubünden hat bisher vertiefte kantonsspezifische Primärquellen. Weitere kantonale Frankenansätze und vollständige europäische Rechtsdetails werden bewusst nicht als verifiziert ausgegeben.</p></div>';
}
function library(){if(window.ATLAS_STRUCTURE_V13)return window.ATLAS_STRUCTURE_V13.browse(null);
return '<span class="eyebrow">FACHBIBLIOTHEK / '+detailCount+' THEMEN</span><h1>Wissensbibliothek</h1><p class="lead">Jeder Artikel führt dich von der einfachen Definition zur Systematik, über Prüfschritte bis zu Gesetzesgrundlagen und verbundenen Themen.</p><div class="toolbar"><input class="input" id="libraryFilter" style="flex:1;min-width:230px" placeholder="Artikel und Themen filtern …"><select class="select" id="libraryCategory"><option>Alle Themen</option>'+sections.map(c=>'<option>'+E(c)+'</option>').join("")+'</select><span class="count" id="libraryCount"></span></div><div id="libraryResults"></div>';
}
function libraryDraw(){if(window.ATLAS_STRUCTURE_V13)return window.ATLAS_STRUCTURE_V13.bindBrowse();const q=$("libraryFilter").value.trim().toLowerCase(),cat=$("libraryCategory").value;const found=D.topics.filter(t=>(cat==="Alle Themen"||t.category===cat)&&[t.title,t.short,t.summary,...t.sections.map(s=>s.heading),...(t.dossier?.chapters||[]).flat(),...(D.v7Deep?.[t.id]?.chapters||[]).flat(),...(D.v7Deep?.[t.id]?.faq||[]).flat(),t.dossier?.research||""].join(" ").toLowerCase().includes(q));$("libraryCount").textContent=found.length+" gefunden";$("libraryResults").innerHTML=found.length?found.map(t=>card(url(t.id),t.short,t.title,t.summary)).join(""):'<div class="empty">Kein Artikel gefunden. Versuche einen anderen Begriff.</div>';$("libraryResults").className="cards"}
function articlePage(id){
const t=A(id);if(!t)return missing();let legal=D.laws.filter(l=>t.lawIds.includes(l.id));let relations=D.edges.filter(e=>e.from===id||e.to===id);const related=[...new Set([...t.related,...relations.map(e=>e.from===id?e.to:e.from)])].filter(x=>A(x)&&x!==id);
return crumb([["#/start","Start"],["#/wissen","Wissensbibliothek"],["",t.title]])+'<div class="articlegrid"><article class="articlemain"><span class="eyebrow">'+E(t.category)+' · FACHARTIKEL</span><h1>'+E(t.title)+'</h1><p class="lead">'+E(t.summary)+'</p><div class="toolbar"><button class="btn minor small" id="favBtn" data-id="'+E(id)+'">'+(favorites.includes(id)?"★ Gemerkt":"☆ Artikel merken")+'</button><a class="btn small" href="#/netzwerk?f='+encodeURIComponent(id)+'">✳ Im Netzwerk anzeigen</a><button class="btn small" id="printArticle">Drucken</button><a class="btn small" href="'+(window.ATLAS_READER_V14?.has(t.id)?"#v14-reader":"#v12-academic")+'" data-scroll="'+(window.ATLAS_READER_V14?.has(t.id)?"v14-reader":"v12-academic")+'">↘ Wissenschaftlich vertiefen</a></div>'+(window.ATLAS_V7?.preview(t)||"")+(window.ATLAS_READER_V14?.article(t)||"")+(window.ATLAS_V5?.articleLead(t)||"")+((D.v9Science?.categories.includes(t.category)||["mig-uno","mig-europa","mig-asyl","mig-familie"].includes(t.id))?"":(window.ATLAS_V6?.articleRatePanel(t)||""))+
t.sections.map((s,i)=>'<section id="kap'+i+'"><h2>'+E(s.heading)+'</h2>'+s.paragraphs.map(p=>'<p>'+E(p)+'</p>').join("")+'</section>').join("")+(D.v9Science?.categories.includes(t.category)?"":(window.ATLAS_V5?.articleDossier(t)?"<details class=\"v13-supplement\"><summary>Zusätzliches Fachdossier und Praxisbeispiele öffnen</summary>"+window.ATLAS_V5.articleDossier(t)+"</details>":""))+(window.ATLAS_READER_V14?.has(t.id)?'<details class="v14-legacy"><summary>Weitere Handbuchkapitel und Fachfragen anzeigen</summary>'+(window.ATLAS_V7?.article(t)||"")+'</details>':(window.ATLAS_V7?.article(t)||""))+(window.ATLAS_DEPTH_V11?.render(t)?"<details class=\"v13-supplement\"><summary>Zusätzliche vertiefende Fallanalyse öffnen</summary>"+window.ATLAS_DEPTH_V11.render(t)+"</details>":"")+(window.ATLAS_ACADEMIC_V12?.article(t)||"")+(window.ATLAS_EVIDENCE_UI_V13?.article(t)||"")+(window.ATLAS_HUMANITIES?.perspective(t)||"")+(window.ATLAS_MIGRATION?.articleSupplement(t)||"")+
'<section id="pruef"><h2>'+(D.v9Science?.categories.includes(t.category)?"Leitfragen zur fachlichen Einordnung":"Prüfschritte für die Praxis")+'</h2><div class="panel"><div class="steps">'+t.steps.map(x=>'<div class="step"><strong>'+E(x)+'</strong></div>').join("")+'</div></div></section>'+
'<details id="gesetze" class="v13-supplement"><summary>Weitere gesetzliche Grundlagen (ergänzende Übersicht)</summary><section><div class="panel">'+(legal.length?legal.map(l=>'<div class="listline"><strong>'+lawLink(l)+'</strong><p>'+E(l.meaning)+'</p></div>').join(""):'<p>Für diesen Bereich ist vor allem das verlinkte Spezialrecht und gegebenenfalls kantonales Recht zu prüfen; eine abschliessende Artikelliste liegt noch nicht vor.</p>')+'</div></section></details>'+
'<details id="quellen" class="v13-supplement"><summary>Weitere amtliche Fachmaterialien anzeigen</summary><section><div class="panel">'+sourceList(t.sources)+'</div></section></details>'+
'<section id="beziehungen"><h2>Verbindungen und Schnittstellen</h2><div class="cards">'+related.slice(0,6).map(r=>{let x=A(r);return card(url(r),x.short,x.title,x.summary)}).join("")+(related.length>6?'<div class="v13-relatedMore"><details><summary>Weitere '+(related.length-6)+' Verbindungen öffnen</summary><div class="cards">'+related.slice(6).map(r=>{let x=A(r);return card(url(r),x.short,x.title,x.summary)}).join("")+'</div></details></div>':'')+'</div></section>'+
'<div class="warn"><b>Fachhinweis:</b> '+E(t.caution)+' Die Darstellung ist eine didaktische Zusammenfassung und kein abschliessendes, stets aktuelles Rechtsgutachten. Überprüfe vor einem verbindlichen Entscheid den amtlichen Gesetzestext und die zuständige Stelle.</div></article>'+
'<aside class="toc"><h4>IN DIESEM ARTIKEL</h4>'+t.sections.map((s,i)=>'<a href="#kap'+i+'" data-scroll="kap'+i+'">'+E(s.heading)+'</a>').join("")+(window.ATLAS_V5?.toc(t)||"")+(window.ATLAS_V7?.toc(t)||"")+(window.ATLAS_READER_V14?.toc(t)||"")+(window.ATLAS_ACADEMIC_V12?.toc(t)||"")+(window.ATLAS_EVIDENCE_UI_V13?.toc(t)||"")+'<a href="#v6-betraege" data-scroll="v6-betraege">Tarife und Beträge 2026</a><a href="#v6-method" data-scroll="v6-method">Rechenwege</a>'+'<a href="#pruef" data-scroll="pruef">Prüfschritte</a><a href="#gesetze" data-scroll="gesetze">Rechtsgrundlagen</a><a href="#quellen" data-scroll="quellen">Quellen</a><a href="#beziehungen" data-scroll="beziehungen">Verbindungen</a><h4 class="related">DIESES THEMA</h4><a href="#/netzwerk?f='+encodeURIComponent(id)+'">✳ Im Systemnetz fokussieren</a><a href="#/assistent?q='+encodeURIComponent(t.short)+'">⌕ Dazu eine Frage stellen</a>'+(window.ATLAS_V5?.rail(t)||"")+'</aside></div>';
}
function listCantons(){return '<span class="eyebrow">26 KANTONE · FÖDERALES RECHT</span><h1>Sozialhilfe der 26 Kantone</h1><p class="lead">Alle Kantone sind zugänglich. Für Graubünden sind konkrete amtliche kantonale Grundlagen eingebunden; die anderen Kantonsprofile enthalten ein ehrliches Vergleichsraster und einen Zugang zur SKOS-Rechtsübersicht.</p><div class="toolbar"><input id="cantFilter" class="input" placeholder="Kanton suchen …"><a class="btn minor" href="#/vergleich">Zwei Kantone vergleichen ⇄</a></div><div id="cantList" class="cards"></div><div class="note"><b>Was ist unterschiedlich?</b><p>Rechtsgrundlagen, Vollzug, Grundbedarf, Wohnkosten, Gesundheit, SIL, Integrationsleistungen und Verfahren können voneinander abweichen. Ohne geprüfte kantonale Quellen nennen wir bewusst keine vermeintlich verbindlichen Zahlen.</p></div>'}
function cantonDraw(){const q=$("cantFilter").value.toLowerCase();const found=D.cantons.filter(c=>(c.name+" "+c.id).toLowerCase().includes(q));$("cantList").innerHTML=found.map(c=>card("#/kanton/"+c.id,c.id,c.name,c.level)).join("")}
function cantonPage(id){const c=region(id);if(!c)return missing();const isGR=id==="GR";const files=isGR?[D.S.grGes,D.S.grP,D.S.grC,D.S.grKom]:[D.S.skosR,D.S.skosW];return crumb([["#/start","Start"],["#/kantone","Kantone"],["",c.name]])+'<span class="eyebrow">KANTONSPROFIL · '+E(id)+'</span><h1>'+E(c.name)+'</h1>'+bubble(c.level,!isGR)+'<p class="lead">Sozialhilfeprofil zur Fallbearbeitung mit fünf Analyseebenen. Die konkrete Anwendung richtet sich nach aktuellem kantonalem und kommunalem Recht.</p><div class="gridTwo"><div class="panel"><h3>Materielle Grundsicherung</h3><p>Grundbedarf, anerkannte Wohnkosten und medizinische Grundversorgung systematisch auseinanderhalten.</p><div>'+al("grundbedarf","Grundbedarf")+' · '+al("wohnkosten","Wohnkosten")+' · '+al("medizinsh","Gesundheit")+'</div></div><div class="panel"><h3>Situationsbedingte Leistungen</h3><p>Bedarf, Kostenträger, Angemessenheit, Ermessensspielraum und Entscheidbegründung prüfen.</p><div>'+al("sil","SIL-Fachartikel")+' · '+al("subsidiaritaet","Subsidiarität")+'</div></div><div class="panel"><h3>Integration & Kooperation</h3><p>IV, ALV, Familienleistungen, Arbeit, Bildung und Netzwerkarbeit als Schnittstellen berücksichtigen.</p><div>'+al("integration","Integration")+' · '+al("iv","IV")+' · '+al("alv","ALV")+'</div></div><div class="panel"><h3>Verfahren & Ablösung</h3><p>Zuständigkeit, Akten, Verfügung, Rechtsmittel und langfristige Perspektiven strukturieren.</p><div>'+al("verfahren","Verfahrensartikel")+' · '+al("sozialhilfe","Grundlagen")+'</div></div></div>'+
(isGR?'<div class="note"><b>Graubünden – konkret belegt</b><p>Die materielle Sozialhilfe liegt grundsätzlich bei den Gemeinden. Das Sozialhilfegesetz BR 546.100 und das kantonale Unterstützungsgesetz BR 546.250 sind wichtige Rechtsgrundlagen. Beachte Handbuch, Praxishilfen und die jeweils aktuelle Fassung.</p></div>':'<div class="warn"><b>Offener Datenstand:</b> Ein kantonaler Gesetzeseinstieg ist verlinkt. Konkrete Mietzinsrichtwerte, Frankenbeträge, Verfahrensfristen, Vollzugsweisungen und aktuelle Einzelfallpraxis sind hier aber noch nicht systematisch geprüft. Bitte den amtlichen Rechtsstand konsultieren.</div>')+
'<h2>Fachliche Prüfreihenfolge</h2><div class="panel"><div class="steps">'+["Aufenthalt, Status und örtliche Zuständigkeit klären","Aktuellen Bedarf, Mittel und vorrangige Ansprüche erfassen","Materielle Grundsicherung nach kantonalem Recht bestimmen","SIL, Integration und individuelle Umstände beurteilen","Entscheid, Verfahren und Rechtsmittel prüfen"].map(x=>'<div class="step"><strong>'+E(x)+'</strong></div>').join("")+'</div></div><h2>Kantonale Gesetzesgrundlagen</h2><div class="panel">'+(c.lawLinks||[]).map(x=>'<div class="listline"><strong><a href="'+E(x.url)+'" target="_blank" rel="noopener noreferrer">'+E(x.label)+' ↗</a></strong><small>Kantonaler Rechtstext; auf aktuellen Stand prüfen</small></div>').join("")+'</div><h2>Weitere amtliche und fachliche Quellen</h2><div class="panel">'+sourceList([...(c.sources||[]),...files])+'</div><div class="toolbar"><a class="btn primary" href="#/falllabor">Praxisfall bearbeiten</a><a class="btn minor" href="#/vergleich">Kantonsvergleich</a></div>'+(window.ATLAS_V5?.cantonDetail(c)||"")+(window.ATLAS_V6?.extraCanton(c)||"")+(window.ATLAS_V7?.canton(c)||"")}
function lands(){return '<span class="eyebrow">EUROPA · LANDESSYSTEME</span><h1>Europäische Sozialsysteme</h1><p class="lead">Sechs Länder als zugängliche Wissensprofile mit Verbindung zum grenzüberschreitenden Koordinationsrecht.</p><div class="cards">'+D.countries.map(c=>card("#/land/"+c.id,c.id,c.name,c.description)).join("")+'</div><div class="note"><b>Gemeinsame Regeln?</b><p>Die europäische Sozialversicherungskoordination koordiniert Zuständigkeiten und bestimmte Ansprüche. Sie harmonisiert nicht sämtliche nationalen Leistungssätze. '+al("international","Zum Koordinationsrecht")+'</p></div>'}
function landPage(id){const c=country(id);if(!c)return missing();return crumb([["#/laender","Europa"],["",c.name]])+'<span class="eyebrow">LÄNDERPROFIL · '+c.id+'</span><h1>'+E(c.name)+'</h1><p class="lead">'+E(c.description)+'</p>'+(window.ATLAS_V5?.countryLead(c)||"")+'<h2>Wichtige Sicherungszweige</h2><div class="cards">'+c.sectors.map((s,i)=>card("#/assistent?q="+encodeURIComponent(s),["01","02","03","04","05"][i],s,"Frage zu diesem Themenfeld stellen")).join("")+'</div><h2>Wissen nach Themenbereichen</h2>'+(c.chapters||[]).map(ch=>'<section class="panel"><h3>'+E(ch.title)+'</h3><p>'+E(ch.text)+'</p></section>').join("")+(window.ATLAS_V5?.countryDetail(c)||"")+(window.ATLAS_V6?.extraCountry(c)||"")+(window.ATLAS_V7?.country(c)||"")+'<h2>Grenzüberschreitende Fälle</h2><div class="panel"><p>Für Grenzgänger, Auswanderung, Entsendung und Erwerbstätigkeit in mehreren Staaten braucht es eine separate Prüfung: Welches Abkommen gilt, welcher Staat ist zuständig, welche Versicherungszeiten werden berücksichtigt und welche Ansprüche dürfen exportiert werden?</p><p>'+al("international","Koordination erklärt")+' · '+al("europa","Ländervergleich")+'</p></div><h2>Offizielle Informationsstellen</h2><div class="panel"><a href="'+E(c.url)+'" target="_blank" rel="noopener noreferrer">Offizielle Stelle für '+E(c.name)+' ↗</a><div class="links-list">'+(c.sources||[]).map(s=>'<a class="listline" href="'+E(s.url)+'" target="_blank" rel="noopener noreferrer"><strong>'+E(s.label)+' ↗</strong></a>').join("")+'</div><p class="count">Das Profil ist noch kein vollständiger Katalog sämtlicher nationaler Leistungen und Sozialgesetzbücher.</p></div>'}
function laws(){if(window.ATLAS_LAW_V13)return window.ATLAS_LAW_V13.page();return '<span class="eyebrow">GESETZGEBUNG · NACHWEISE</span><h1>Rechtsbibliothek</h1><p class="lead">Ausgewählte Gesetzesartikel, thematische Bedeutung und Direktlinks zu den amtlichen Texten. Durchsuche die Normen nach Gesetz, Artikel oder Stichwort.</p><div class="toolbar"><input id="lawQuery" class="input" placeholder="z.B. ATSG, ELG, IVG …" style="flex:1;min-width:200px"><select id="lawArea" class="select"><option value="">Alle Rechtsgebiete</option>'+[...new Set(D.laws.map(l=>l.area))].map(s=>'<option>'+E(s)+'</option>').join("")+'</select></div><div id="lawList"></div><div class="warn"><b>Rechtsstand:</b> Die ausgewählten Normen sind als Einstieg recherchiert. Für Anwendungen sind aktueller Wortlaut, Ausnahmen, Übergangsrecht und kantonale Vorschriften verbindlich zu prüfen.</div>'}
function lawDraw(){const q=$("lawQuery").value.toLowerCase(),area=$("lawArea").value;const found=D.laws.filter(l=>(!area||l.area===area)&&[l.code,l.title,l.meaning,l.area].join(" ").toLowerCase().includes(q));$("lawList").innerHTML=found.length?found.map(l=>'<div class="panel"><div class="flexBetween"><span class="eyebrow">'+E(l.area)+'</span>'+bubble(l.code)+'</div><h3>'+lawLink(l)+'</h3><p>'+E(l.meaning)+'</p><p class="count">Verknüpft: '+l.topics.filter(id=>A(id)).map(id=>al(id,A(id).short)).join(" · ")+'</p></div>').join(""):'<div class="empty">Keine passende Rechtsnorm in dieser kuratierten Sammlung gefunden.</div>'}
function comparison(){return '<span class="eyebrow">VERGLEICHSWERKZEUG</span><h1>Systeme gegenüberstellen</h1><p class="lead">Vergleiche die grundlegenden Strukturen von Kantonen oder Ländern. Rechtlich nicht überprüfte Angaben sind ausdrücklich als offen markiert.</p><div class="tabstrip"><button id="comparisonModeCant" class="active">Kantone</button><button id="comparisonModeLand">Länder</button></div><div class="toolbar"><select class="select" id="compareA"></select><span>versus</span><select class="select" id="compareB"></select></div><div id="compareResult"></div>'}
let compMode="kantone";
