function answerStudio(){return '<span class="eyebrow">QUELLENBASIERTE WISSENSSUCHE</span><h1>Frage SOCIAL ATLAS</h1><p class="lead">Schreibe eine Frage in Alltagssprache. Der Assistent sucht passende Artikel, Rechtsgrundlagen und erklärt die wichtigsten Zusammenhänge aus unserer Wissensdatenbank.</p><div class="warn"><b>Technischer Status:</b> Dieser Assistent ist noch keine externe generative KI. Er stellt quellenbasierte Antworten aus lokalen Texten zusammen. Für ein echtes Sprachmodell braucht es einen geschützten Backend-Dienst und eine kontrollierte Quellenabfrage.</div><div class="panel"><textarea class="textarea" id="askInput" placeholder="Beispiel: Welche Sozialversicherung ist bei längerer Krankheit zuständig und welche Rolle spielen IV, BVG und Sozialhilfe?"></textarea><div class="toolbar"><button class="btn primary" id="askRun">Antwort aus Wissensbasis erstellen ↗</button><button class="btn" id="askSample">Beispielfrage</button></div></div><div id="askResult"></div><h2>Häufige Fragen</h2><div class="cards">'+["Was ist der Unterschied zwischen EL und Sozialhilfe?","Wie funktioniert die IV bei Krankheit?","Wann gibt es Leistungen der ALV?","Was sind situationsbedingte Leistungen?","Welche Versicherung gilt für Grenzgänger?","Wie funktioniert die 13. AHV-Altersrente?"].map((q,i)=>card("#/assistent?q="+encodeURIComponent(q),"0"+(i+1),q,"Passende Inhalte und Rechtsgrundlagen finden")).join("")+'</div>'}
const stop=new Set(["der","die","das","den","dem","des","ein","eine","und","oder","wie","was","bei","ist","sind","für","ich","wir","mit","auf","aus","von","zur","zum","wann","welche","welcher","welches","sich","als","nach","kann","man","werden","gibt","gibt's","gegenüber","zwischen","alle","einem","einer"]);
const synonyms={rente:["ahv","iv","el","bvg"],pension:["ahv","bvg"],krank:["iv","kvg","uvg","medizinsh"],arbeitslos:["alv","uel","sozialhilfe"],zahn:["medizinsh","sil"],miete:["wohnkosten","sozialhilfe"],hilfe:["sozialhilfe","sil"],prämie:["kvg","ipv"],unfall:["uvg","iv"],eu:["international","europa"],grenz:["international"],ausland:["international"],graubünden:["graubuenden","sozialhilfe"],status:["graubuenden","sozialhilfe"],familie:["famz","eo"]};
function tokens(s){return (s.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"").match(/[a-z0-9]{3,}/g)||[]).filter(w=>!stop.has(w))}
function askDo(){const question=$("askInput").value.trim();if(question.length<7){$("askResult").innerHTML='<div class="empty">Bitte formuliere eine ausführlichere Frage.</div>';return}const words=tokens(question),ranked=D.topics.map(t=>{const title=t.title.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"");const body=[t.summary,...t.sections.flatMap(s=>[s.heading,...s.paragraphs]),...(t.dossier?.chapters||[]).flat(),...(D.v7Deep?.[t.id]?.chapters||[]).flat(),...(D.v7Deep?.[t.id]?.faq||[]).flat()].join(" ").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"");let points=words.reduce((p,w)=>p+(title.includes(w)?7:0)+(t.short.toLowerCase().includes(w)?6:0)+(body.includes(w)?1.5:0),0);if(question.toLowerCase().includes(t.short.toLowerCase()))points+=10;for(const [term,ids] of Object.entries(synonyms))if(question.toLowerCase().includes(term)&&ids.includes(t.id))points+=7;return {topic:t,points}}).sort((a,b)=>b.points-a.points).filter(x=>x.points>0).slice(0,5);
if(!ranked.length){$("askResult").innerHTML='<div class="empty">Ich finde dazu keine belastbare Antwort in der Datenbank. Versuche eine Frage mit einem Versicherungszweig oder Sozialhilfebegriff.</div>';return}
const top=ranked[0].topic,related=ranked.slice(1,4).map(x=>x.topic),norms=[...new Map(ranked.flatMap(x=>x.topic.lawIds).map(law).filter(Boolean).map(x=>[x.id,x])).values()].slice(0,8);const src=[...new Map(ranked.flatMap(x=>x.topic.sources).map(s=>[s.url,s])).values()].slice(0,7);
$("askResult").innerHTML='<div class="result"><span class="eyebrow">AUS DER WISSENSBASIS ZUSAMMENGESTELLT</span><h2>'+E(top.title)+'</h2><p class="lead">'+E(top.summary)+'</p><div class="note"><b>Einfach erklärt</b><p>'+E(top.sections[0].paragraphs[0])+'</p></div><h3>Fachliche Vertiefung</h3>'+(top.dossier?.chapters||[]).slice(0,3).map(ch=>'<div class="v5-chapter"><h3>'+E(ch[0])+'</h3>'+ch.slice(1).map(p=>'<p>'+E(p)+'</p>').join("")+'</div>').join("")+'<h3>Entscheidende Prüfpunkte</h3><div class="steps">'+top.steps.slice(0,4).map(s=>'<div class="step"><strong>'+E(s)+'</strong></div>').join("")+'</div>'+(related.length?'<h3>Weitere betroffene Systeme</h3><p>'+related.map(t=>al(t.id,t.title)).join(" · ")+'</p>':'')+'<h3>Rechtsgrundlagen</h3><div class="citeList">'+(norms.length?norms.map(l=>'<div class="listline">'+lawLink(l)+'</div>').join(""):'<p>Aktuelles Spezialrecht und kantonale Regelungen prüfen.</p>')+'</div><h3>Quellen</h3>'+sourceList(src)+'<div class="toolbar"><a class="btn primary" href="'+url(top.id)+'">Vertieften Fachartikel öffnen</a><a class="btn" href="#/netzwerk?f='+top.id+'">Vernetzung anzeigen</a></div><div class="warn"><b>Wichtig:</b> Dies ist eine thematische Einordnung auf Basis vorhandener Fachtexte. Die Funktion trifft keine individuelle Anspruchsentscheidung und erfindet keine fehlenden Angaben.</div></div>'}
