function quizDraw(){quizDone=false;const item=QUIZ[quizPos];$("quizPart").innerHTML='<div class="panel"><div class="flexBetween"><span class="eyebrow">FRAGE '+(quizPos+1)+' / '+QUIZ.length+'</span><span class="count">'+quizPoints+' richtige Antworten</span></div><h2>'+E(item[0])+'</h2><div id="quizAnswers">'+item[1].map((a,i)=>'<button class="answer" data-answer="'+i+'">'+E(a)+'</button>').join("")+'</div><div id="quizFeedback"></div></div>';$("quizAnswers").querySelectorAll("[data-answer]").forEach(b=>b.onclick=()=>{if(quizDone)return;quizDone=true;const okay=Number(b.dataset.answer)===item[2];if(okay)quizPoints++;$("quizFeedback").innerHTML='<div class="note"><b>'+(okay?"Richtig!":"Nicht ganz.")+'</b><p>'+E(item[3])+' '+al(item[4],"Fachartikel öffnen →")+'</p></div>';[...$("quizAnswers").children].forEach(x=>{x.disabled=true;x.classList.add(Number(x.dataset.answer)===item[2]?"correct":"incorrect")})})}
