function route(){const hash=location.hash.slice(2).split("?")[0],parts=hash.split("/"),page=parts[0]||"start",id=decodeURIComponent(parts[1]||"");const map={start:home,wissen:library,hilfe:()=>window.ATLAS_V10?.help()||missing(),sozialwissenschaften:()=>window.ATLAS_STRUCTURE_V13?.science()||window.ATLAS_HUMANITIES?.subjects()||missing(),forschungsdossiers:()=>window.ATLAS_READER_V14?.hub()||missing(),studienatlas:()=>window.ATLAS_STUDIES_V15?.overview()||missing(),fachlexikon:()=>window.ATLAS_HUMANITIES?.lexicon()||missing(),migration:()=>window.ATLAS_MIGRATION?.atlas()||missing(),tarife:()=>window.ATLAS_V6?.ratePage()+(window.ATLAS_MIGRATION?.tariffPanel()||"")||missing(),rechner:()=>window.ATLAS_V6?.calculatorsPage()||missing(),netzwerk:network,infografiken:()=>window.ATLAS_VISUAL_V13?.gallery()||missing(),werkzeuge:()=>window.ATLAS_STRUCTURE_V13?.tools()||missing(),kantone:listCantons,laender:lands,recht:laws,glossar:glossary,falllabor:caseLab,assistent:answerStudio,generator:generator,vergleich:comparison,quiz:quiz};let html=page==="artikel"?articlePage(id):page==="studie"?window.ATLAS_STUDIES_V15?.details(id)||missing():page==="kanton"?cantonPage(id):page==="land"?landPage(id):page==="gebiet"?window.ATLAS_STRUCTURE_V13?.browse(id)||missing():page==="grafik"?window.ATLAS_VISUAL_V13?.single(id)||missing():map[page]?.()||missing();$("main").innerHTML=html;const active=["artikel","gebiet"].includes(page)?"wissen":page==="kanton"?"kantone":page==="land"?"laender":page==="grafik"?"infografiken":page;document.querySelectorAll(".nav a").forEach(el=>el.classList.toggle("active",el.dataset.page===active));document.querySelector(".sidebar").classList.remove("open");$("shade").classList.remove("show");document.title=(page==="artikel"?A(id)?.title:"SOCIAL ATLAS")+" · SOCIAL ATLAS";if(document.body){const topic=page==="artikel"?A(id):null;document.body.dataset.atlasArea=topic?(window.ATLAS_STRUCTURE_V13?.mark(topic)||"systeme"):page==="gebiet"?id:page==="sozialwissenschaften"||page==="forschungsdossiers"?"soziologie":"systeme"}window.scrollTo({top:0,behavior:"instant"});bindPage(page,id);if(page==="netzwerk"){let qp=new URLSearchParams(location.hash.split("?")[1]||"");let focus=qp.get("f");if(focus&&A(focus)){graphFocus=focus;graphFilter=A(focus).category;const select=$("graphFilter");if(select)select.value=graphFilter}renderGraph()}}
